          })),
          procuradores: (procuradoresPayload.data ?? []).map((item: any) => ({
            id: item.id,
            nombre: item.nombre,
          })),
        })
      } catch (fetchError) {
        console.error('Error loading receipt filters:', fetchError)
      }
    }

    fetchOptions()

    return () => {
      ignore = true
    }
  }, [])

